66	
67	@RestController
68	@CrossOrigin(exposedHeaders = "errors, content-type")
69	@RequestMapping("/api")
70	public class OwnerRestControllerV1 implements OwnersApi {
71	
72	    /**
73	     * Dedicated audit logger. A single line is emitted here on each successful owner create,
74	     * carrying the new owner's id, customer code and registration date.
75	     */
76	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
77	
78	    /**
79	     * Syntactic validation for an owner email: a non-empty local part, an '@', and a dotted domain
80	     * whose top-level label is at least two letters. Deliberately conservative so plainly malformed
81	     * input (e.g. a value without an '@') is rejected.
82	     */
83	    private static final Pattern EMAIL_PATTERN =
84	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
85	
86	    /**
87	     * Maximum number of owners a single city may hold. A create whose city already contains this many
88	     * owners is rejected with a {@code 409 Conflict} (see {@link #rejectCityAtCapacity}).
89	     */
90	    private static final int MAX_OWNERS_PER_CITY = 50;
91	
92	    /**
93	     * Maximum number of owners that may be registered in a single day. A create made once this many
94	     * owners already carry today's {@code registrationDate} is rejected with a {@code 429 Too Many
95	     * Requests} (see {@link #rejectDailyRegistrationLimitReached}).
96	     */
97	    private static final int MAX_OWNERS_PER_DAY = 100;
98	
99	    /**
100	     * The number of owners that must already carry a given day's {@code registrationDate} before a
101	     * create made that day is flagged with {@code bulkSignupWarning}. Once more than this many owners
102	     * have already been created for the day, the new owner's {@code bulkSignupWarning} is {@code true}.
103	     */
104	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
105	
106	    private final ClinicService clinicService;
107	
108	    private final OwnerMapper ownerMapper;
109	
110	    private final PetMapper petMapper;
111	
112	    private final VisitMapper visitMapper;
113	
114	    public OwnerRestControllerV1(ClinicService clinicService,
115	                                 OwnerMapper ownerMapper,
116	                                 PetMapper petMapper,
117	                                 VisitMapper visitMapper) {
118	        this.clinicService = clinicService;
119	        this.ownerMapper = ownerMapper;
120	        this.petMapper = petMapper;
121	        this.visitMapper = visitMapper;
122	    }
123	
124	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
125	    @Override
126	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
127	        Collection<Owner> owners;
128	        if (lastName != null) {
129	            owners = this.clinicService.findOwnerByLastName(lastName);
130	        } else {
131	            owners = this.clinicService.findAllOwners();
132	        }
133	        if (owners.isEmpty()) {
134	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
135	        }
136	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
137	    }
138	
139	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
140	    @Override
141	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
142	        Owner owner = this.clinicService.findOwnerById(ownerId);
143	        if (owner == null) {
144	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
145	        }
146	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
147	    }
148	
149	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
150	    @Override
151	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
152	        normalizeAddress(ownerFieldsDto);
153	        rejectBlankOwnerFields(ownerFieldsDto);
154	        normalizeTelephone(ownerFieldsDto);
155	        rejectDuplicateTelephone(ownerFieldsDto.getTelephone());
156	        rejectDuplicateHousehold(ownerFieldsDto);
157	        rejectCityAtCapacity(ownerFieldsDto.getCity());
158	        LocalDate registrationDate = effectiveRegistrationDate(ownerFieldsDto.getRegistrationDate());
159	        long registeredThatDay = countRegisteredOn(registrationDate);
160	        rejectDailyRegistrationLimitReached(registrationDate, registeredThatDay);
161	        normalizeEmail(ownerFieldsDto);
162	        HttpHeaders headers = new HttpHeaders();
163	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
164	        owner.setRegistrationDate(registrationDate);
165	        owner.setHouseholdId(HouseholdNormalizer.toHouseholdId(owner.getLastName(), owner.getAddress()));
166	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
167	        owner.setBulkSignupWarning(registeredThatDay > BULK_SIGNUP_WARNING_THRESHOLD);
168	        this.clinicService.saveOwner(owner);
169	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
170	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
171	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
172	        headers.setLocation(UriComponentsBuilder.newInstance()
173	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
174	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
175	    }
176	
177	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
178	    @Override
179	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
180	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
181	        if (currentOwner == null) {
182	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
183	        }
184	        currentOwner.setAddress(ownerFieldsDto.getAddress());
185	        currentOwner.setCity(ownerFieldsDto.getCity());
186	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
187	        currentOwner.setLastName(ownerFieldsDto.getLastName());
188	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
189	        normalizeEmail(ownerFieldsDto);
190	        currentOwner.setEmail(ownerFieldsDto.getEmail());
191	        currentOwner.setHouseholdId(
192	            HouseholdNormalizer.toHouseholdId(currentOwner.getLastName(), currentOwner.getAddress()));
193	        this.clinicService.saveOwner(currentOwner);
194	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
195	    }
196	
197	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
198	    @Transactional
199	    @Override
200	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
201	        Owner owner = this.clinicService.findOwnerById(ownerId);
202	        if (owner == null) {
203	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
204	        }
205	        this.clinicService.deleteOwner(owner);
206	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
207	    }
208	
209	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
210	    @Override
211	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
212	        Owner owner = this.clinicService.findOwnerById(ownerId);
213	        if (owner == null) {
214	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
215	        }
216	        HttpHeaders headers = new HttpHeaders();
217	        Pet pet = petMapper.toPet(petFieldsDto);
218	        owner.setId(ownerId);
219	        pet.setOwner(owner);
220	        pet.getType().setName(null);
221	        this.clinicService.savePet(pet);
222	        PetDto petDto = petMapper.toPetDto(pet);
223	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
224	            .buildAndExpand(pet.getId()).toUri());
225	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
226	    }
227	
228	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
229	    @Override
230	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
231	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
232	        if (currentOwner != null) {
233	            Pet currentPet = this.clinicService.findPetById(petId);
234	            if (currentPet != null) {
235	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
236	                currentPet.setName(petFieldsDto.getName());
237	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
238	                this.clinicService.savePet(currentPet);
239	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
240	            }
241	        }
242	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
243	    }
244	
245	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
246	    @Override
247	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
248	        HttpHeaders headers = new HttpHeaders();
249	        Visit visit = visitMapper.toVisit(visitFieldsDto);
250	        Pet pet = new Pet();
251	        pet.setId(petId);
252	        visit.setPet(pet);
253	        this.clinicService.saveVisit(visit);
254	        VisitDto visitDto = visitMapper.toVisitDto(visit);
255	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
256	            .buildAndExpand(visit.getId()).toUri());
257	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
258	    }
259	
260	
261	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
262	    @Override
263	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
264	        Owner owner = this.clinicService.findOwnerById(ownerId);
265	        if (owner != null) {
266	            Pet pet = owner.getPet(petId);
267	            if (pet != null) {
268	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
269	            }
270	        }
271	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
272	    }
273	
274	    /**
275	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
276	     * {@code telephone} is missing (null) or blank (empty or whitespace only). Bean Validation on
277	     * the request body already rejects null and empty values, but permits whitespace-only strings
278	     * for fields without a stricter pattern (e.g. {@code city}, {@code address}); this guard closes
279	     * that gap so every required field must carry a non-blank value.
280	     *
281	     * @param ownerFieldsDto the submitted owner fields
282	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
283	     */
284	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
285	        List<String> missing = new ArrayList<>();
286	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
287	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
288	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
289	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
290	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
291	        if (!missing.isEmpty()) {
292	            throw new InvalidOwnerFieldsException(missing);
293	        }
294	    }
295	
296	    private void addIfBlank(List<String> missing, String fieldName, String value) {
297	        if (value == null || value.isBlank()) {
298	            missing.add(fieldName);
299	        }
300	    }
301	
302	    /**
303	     * Normalizes the submitted {@code address} on create to its canonical form (see
304	     * {@link AddressNormalizer#normalize}) and writes it back onto the request so it is the value
305	     * stored and returned, and the form every later address comparison (the required-field check,
306	     * household duplicate detection and the shared household id) is judged on. A null address is left
307	     * untouched so {@link #rejectBlankOwnerFields} still reports it as missing; a value that is blank
308	     * after normalization likewise reduces to the empty string and is rejected there.
309	     *
310	     * @param ownerFieldsDto the submitted owner fields
311	     */
312	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
313	        String address = ownerFieldsDto.getAddress();
314	        if (address == null) {
315	            return;
316	        }
317	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(address));
318	    }
319	
320	    /**
321	     * Normalizes the submitted {@code telephone} on create to its canonical form (see
322	     * {@link TelephoneNormalizer#normalize}) and writes it back onto the request so it is the value
323	     * stored and returned. Any input that does not reduce to a valid telephone is rejected with a
324	     * {@code 400 Bad Request}.
325	     *
326	     * @param ownerFieldsDto the submitted owner fields (its {@code telephone} is non-blank here,
327	     *                       {@link #rejectBlankOwnerFields} having already run)
328	     * @throws InvalidOwnerFieldsException if the telephone cannot be normalized to a valid value
329	     */
330	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
331	        String normalized = TelephoneNormalizer.normalize(ownerFieldsDto.getTelephone())
332	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("telephone")));
333	        ownerFieldsDto.setTelephone(normalized);
334	    }
335	
336	    /**
337	     * Normalizes an optionally-supplied {@code email}. When absent (null) or blank the field is left
338	     * untouched (email is optional). When present it is trimmed and, after validating that it is a
339	     * syntactically valid address, written back lower-cased so it is the value stored and returned.
340	     * Any present-but-invalid address is rejected with a {@code 400 Bad Request}.
341	     *
342	     * @param ownerFieldsDto the submitted owner fields
343	     * @throws InvalidOwnerFieldsException if the email is present but not a syntactically valid address
344	     */
345	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
346	        String email = ownerFieldsDto.getEmail();
347	        if (email == null || email.isBlank()) {
348	            return;
349	        }
350	        email = email.trim();
351	        if (!EMAIL_PATTERN.matcher(email).matches()) {
352	            throw new InvalidOwnerFieldsException(List.of("email"));
353	        }
354	        ownerFieldsDto.setEmail(email.toLowerCase(Locale.ROOT));
355	    }
356	
357	    /**
358	     * Rejects creating an owner whose normalized telephone is already used by any other owner.
359	     * Both the submitted telephone and every existing owner's stored telephone are reduced to their
360	     * {@linkplain TelephoneNormalizer#toComparisonKey comparison key} before comparison, so equality
361	     * is judged on that key alone. A match is reported as a {@code 409 Conflict}.
362	     *
363	     * @param normalizedTelephone the submitted telephone, already reduced to its canonical form by
364	     *                            {@link #normalizeTelephone}
365	     * @throws DuplicateOwnerTelephoneException if another owner already uses the same telephone
366	     */
367	    private void rejectDuplicateTelephone(String normalizedTelephone) {
368	        String comparisonKey = TelephoneNormalizer.toComparisonKey(normalizedTelephone);
369	        boolean inUse = this.clinicService.findAllOwners().stream()
370	            .map(Owner::getTelephone)
371	            .filter(Objects::nonNull)
372	            .map(TelephoneNormalizer::toComparisonKey)
373	            .anyMatch(comparisonKey::equals);
374	        if (inUse) {
375	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
376	        }
377	    }
378	
379	    /**
380	     * Rejects creating an owner who shares a household with any existing owner, unless the request
381	     * opts in with {@code sharesHousehold} set to {@code true}. Two owners share a household when they
382	     * have the same {@code lastName} and {@code address}, compared case-insensitively and with runs of
383	     * whitespace collapsed (see {@link HouseholdNormalizer}); the submitted fields and every existing
384	     * owner's stored fields are reduced to their {@linkplain HouseholdNormalizer#toComparisonKey
385	     * comparison key} before comparison. A match is reported as a {@code 409 Conflict}.
386	     *
387	     * @param ownerFieldsDto the submitted owner fields (its {@code lastName} and {@code address} are
388	     *                       non-blank here, {@link #rejectBlankOwnerFields} having already run)
389	     * @throws DuplicateOwnerHouseholdException if another owner already shares the household and the
390	     *                                          request did not opt in with {@code sharesHousehold}
391	     */
392	    /**
393	     * Counts the existing owners (before this create) whose {@code firstName} and {@code lastName}
394	     * both match the submitted values, compared case-insensitively. The count reflects only owners
395	     * already persisted at the time of the create, so the owner being created is never included.
396	     *
397	     * @param firstName the submitted first name (non-blank here, {@link #rejectBlankOwnerFields}
398	     *                  having already run)
399	     * @param lastName  the submitted last name (non-blank here)
400	     * @return the number of existing owners sharing the same first and last name
401	     */
402	    private int countNamesakes(String firstName, String lastName) {
403	        return (int) this.clinicService.findAllOwners().stream()
404	            .filter(owner -> firstName.equalsIgnoreCase(owner.getFirstName())
405	                && lastName.equalsIgnoreCase(owner.getLastName()))
406	            .count();
407	    }
408	
409	    /**
410	     * Rejects creating an owner whose city already holds {@link #MAX_OWNERS_PER_CITY} or more owners.
411	     * The submitted city is compared case-insensitively against every existing owner's stored city; a
412	     * city that is already at (or over) capacity is reported as a {@code 409 Conflict}.
413	     *
414	     * @param city the submitted city (non-blank here, {@link #rejectBlankOwnerFields} having already
415	     *             run)
416	     * @throws OwnerCityAtCapacityException if the city already contains the maximum number of owners
417	     */
418	    private void rejectCityAtCapacity(String city) {
419	        long ownersInCity = this.clinicService.findAllOwners().stream()
420	            .map(Owner::getCity)
421	            .filter(Objects::nonNull)
422	            .filter(city::equalsIgnoreCase)
423	            .count();
424	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
425	            throw new OwnerCityAtCapacityException(city);
426	        }
427	    }
428	
429	    /**
430	     * Resolves the effective registration date for a create, rolled onto a business day. The
431	     * supplied date is used when present, otherwise the server's current date; either way the result
432	     * is rolled forward to the next Monday when it falls on a Saturday or Sunday (see
433	     * {@link BusinessDayAdjuster#toBusinessDay}). Every value derived from the registration date - the
434	     * stored {@code registrationDate}, the membership number's year segment and the daily
435	     * create-limit's per-day count - is judged on this adjusted date.
436	     *
437	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} to
438	     *                                 default to the server's current date
439	     * @return the effective registration date, guaranteed to fall on a business day
440	     */
441	    private LocalDate effectiveRegistrationDate(LocalDate suppliedRegistrationDate) {
442	        LocalDate registrationDate =
443	            suppliedRegistrationDate != null ? suppliedRegistrationDate : LocalDate.now();
444	        return BusinessDayAdjuster.toBusinessDay(registrationDate);
445	    }
446	
447	    /**
448	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
449	     * created for the given business day, judged by their stored {@code registrationDate}. Only owners
450	     * already persisted (before this create) are counted, and only those whose {@code registrationDate}
451	     * equals the adjusted registration date; a day at (or over) that limit is reported as a {@code 429
452	     * Too Many Requests}.
453	     *
454	     * @param registrationDate   the create's effective registration date, already rolled onto a
455	     *                           business day by {@link #effectiveRegistrationDate}
456	     * @param registeredThatDay  the number of owners already persisted (before this create) whose
457	     *                           {@code registrationDate} equals {@code registrationDate}
458	     * @throws OwnerDailyRegistrationLimitException if that day has already reached the maximum number of
459	     *                                              owner registrations
460	     */
461	    private void rejectDailyRegistrationLimitReached(LocalDate registrationDate, long registeredThatDay) {
462	        if (registeredThatDay >= MAX_OWNERS_PER_DAY) {
463	            throw new OwnerDailyRegistrationLimitException(registrationDate);
464	        }
465	    }
466	
467	    /**
468	     * Counts the owners already persisted (before this create) whose stored {@code registrationDate}
469	     * equals the given day. This is the shared per-day accumulation both the daily create-limit and the
470	     * bulk-signup warning are judged on.
471	     *
472	     * @param registrationDate the create's effective registration date, already rolled onto a business
473	     *                         day by {@link #effectiveRegistrationDate}
474	     * @return the number of existing owners registered on that day
475	     */
476	    private long countRegisteredOn(LocalDate registrationDate) {
477	        return this.clinicService.findAllOwners().stream()
478	            .map(Owner::getRegistrationDate)
479	            .filter(registrationDate::equals)
480	            .count();
481	    }
482	
483	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
484	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
485	            return;
486	        }
487	        String comparisonKey = HouseholdNormalizer.toComparisonKey(
488	            ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
489	        boolean inUse = this.clinicService.findAllOwners().stream()
490	            .filter(owner -> owner.getLastName() != null && owner.getAddress() != null)
491	            .map(owner -> HouseholdNormalizer.toComparisonKey(owner.getLastName(), owner.getAddress()))
492	            .anyMatch(comparisonKey::equals);
493	        if (inUse) {
494	            throw new DuplicateOwnerHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
495	        }
496	    }
497	}
